            real(wp) :: cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26, cs27, cs28, cs29
            real(wp) :: cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39, cs40, cs44, cs45
            real(wp) :: cs46, cs47, cs48, cs49, cs50, cs51, cs52, cs53, cs54, cs55, cs56, cs57, cs58
            real(wp) :: cs59, cs60, cs61, cs62, cs63, cs64, cs65, cs66, cs67, cs68, cs69, cs70, cs71
            real(wp) :: cs72, cs73, cs74, cs75, cs76, cs77, cs78, cs79, cs80, cs81, cs82, cs83, cs84
            real(wp) :: cs85, cs86, cs87, cs88, cs89, cs90, cs91, cs92, cs93, cs94
            !> Subexpressions only the q kind needs
            real(wp) :: cs2, cs12, cs13, cs41, cs42, cs43, cs95, cs96, cs97, cs98, cs99, cs100
            real(wp) :: cs101, cs102, cs103, cs104, cs105, cs106, cs107, cs108, cs109

            acc_ps0_p1 = 0.0_wp
            acc_ps0_p2 = 0.0_wp
            acc_ps0_p3 = 0.0_wp
            acc_ps0_q = 0.0_wp
            acc_ps1_p1_0 = 0.0_wp
            acc_ps1_p1_1 = 0.0_wp
            acc_ps1_p1_2 = 0.0_wp
            acc_ps1_p2_0 = 0.0_wp
            acc_ps1_p2_1 = 0.0_wp
            acc_ps1_p2_2 = 0.0_wp
            acc_ps1_p3_0 = 0.0_wp
            acc_ps1_p3_1 = 0.0_wp
            acc_ps1_p3_2 = 0.0_wp
            acc_ps1_q_0 = 0.0_wp
            acc_ps1_q_1 = 0.0_wp
            acc_ps1_q_2 = 0.0_wp
            acc_ps2_p1_00 = 0.0_wp
            acc_ps2_p1_01 = 0.0_wp
            acc_ps2_p1_02 = 0.0_wp
            acc_ps2_p1_11 = 0.0_wp
            acc_ps2_p1_12 = 0.0_wp
            acc_ps2_p1_22 = 0.0_wp
            acc_ps2_p2_00 = 0.0_wp
            acc_ps2_p2_01 = 0.0_wp
            acc_ps2_p2_02 = 0.0_wp
            acc_ps2_p2_11 = 0.0_wp
            acc_ps2_p2_12 = 0.0_wp
            acc_ps2_p2_22 = 0.0_wp
            acc_ps2_p3_00 = 0.0_wp
            acc_ps2_p3_01 = 0.0_wp
            acc_ps2_p3_02 = 0.0_wp
            acc_ps2_p3_11 = 0.0_wp
            acc_ps2_p3_12 = 0.0_wp
            acc_ps2_p3_22 = 0.0_wp
            acc_ps2_q_00 = 0.0_wp
            acc_ps2_q_01 = 0.0_wp
            acc_ps2_q_02 = 0.0_wp
            acc_ps2_q_11 = 0.0_wp
            acc_ps2_q_12 = 0.0_wp
            acc_ps2_q_22 = 0.0_wp
            acc_ps3_p1_000 = 0.0_wp
            acc_ps3_p1_001 = 0.0_wp
            acc_ps3_p1_002 = 0.0_wp
            acc_ps3_p1_011 = 0.0_wp
            acc_ps3_p1_012 = 0.0_wp
            acc_ps3_p1_022 = 0.0_wp
            acc_ps3_p1_111 = 0.0_wp
            acc_ps3_p1_112 = 0.0_wp
            acc_ps3_p1_122 = 0.0_wp
            acc_ps3_p1_222 = 0.0_wp
            acc_ps3_p2_000 = 0.0_wp
            acc_ps3_p2_001 = 0.0_wp
            acc_ps3_p2_002 = 0.0_wp
            acc_ps3_p2_011 = 0.0_wp
            acc_ps3_p2_012 = 0.0_wp
            acc_ps3_p2_022 = 0.0_wp
            acc_ps3_p2_111 = 0.0_wp
            acc_ps3_p2_112 = 0.0_wp
            acc_ps3_p2_122 = 0.0_wp
            acc_ps3_p2_222 = 0.0_wp
            acc_ps3_p3_000 = 0.0_wp
            acc_ps3_p3_001 = 0.0_wp
            acc_ps3_p3_002 = 0.0_wp
            acc_ps3_p3_011 = 0.0_wp
            acc_ps3_p3_012 = 0.0_wp
            acc_ps3_p3_022 = 0.0_wp
            acc_ps3_p3_111 = 0.0_wp
            acc_ps3_p3_112 = 0.0_wp
            acc_ps3_p3_122 = 0.0_wp
            acc_ps3_p3_222 = 0.0_wp
            acc_ps3_q_000 = 0.0_wp
            acc_ps3_q_001 = 0.0_wp
            acc_ps3_q_002 = 0.0_wp
            acc_ps3_q_011 = 0.0_wp
            acc_ps3_q_012 = 0.0_wp
            acc_ps3_q_022 = 0.0_wp
            acc_ps3_q_111 = 0.0_wp
            acc_ps3_q_112 = 0.0_wp
            acc_ps3_q_122 = 0.0_wp
            acc_ps3_q_222 = 0.0_wp

            do ia = 1, n
               x = sqrt(d(1, ia)*d(1, ia) + d(2, ia)*d(2, ia) + d(3, ia)*d(3, ia))
               u = exp(bk3*(x - radii(ia)))
               cs0 = (u*u)
               cs1 = (u*u*u)
               cs3 = 1.0_wp/x
               cs4 = blend_k*cs3
               cs5 = cs4*d(1, ia)
               cs6 = (1.0_wp/3.0_wp)*u
               cs7 = cs4*cs6
               cs8 = (2.0_wp/3.0_wp)*cs0
               cs9 = cs4*cs8
               cs10 = blend_k*cs1
               cs11 = cs10*cs3
               cs14 = (d(1, ia)*d(1, ia))
               cs15 = blend_k*x
               cs16 = (1.0_wp/3.0_wp)*cs15
               cs17 = (x*x)
               cs18 = -cs17
               cs19 = cs14 + cs18
               cs20 = (x*x*x)
               cs21 = 1.0_wp/cs20
               cs22 = blend_k*cs21
               cs23 = cs22*cs6
               cs24 = d(1, ia)*d(2, ia)
               cs25 = cs23*(cs16 + 1.0_wp)
               cs26 = cs25*d(3, ia)
               cs27 = (d(2, ia)*d(2, ia))
               cs28 = cs18 + cs27
               cs29 = (d(3, ia)*d(3, ia))
               cs30 = cs18 + cs29
               cs31 = (2.0_wp/3.0_wp)*cs15
               cs32 = cs22*cs8
               cs33 = cs32*(cs31 + 1.0_wp)
               cs34 = cs33*d(3, ia)
               cs35 = cs14*cs15
               cs36 = cs10*cs21
               cs37 = cs36*(cs15 + 1.0_wp)
               cs38 = cs37*d(3, ia)
               cs39 = cs15*cs27
               cs40 = cs15*cs29
               cs44 = -blend_k*cs20
               cs45 = (blend_k*blend_k)
               cs46 = cs14*cs45
               cs47 = (1.0_wp/9.0_wp)*cs46
               cs48 = 3.0_wp*cs14
               cs49 = cs35 + cs48
               cs50 = 1.0_wp/(x*x*x*x*x)
               cs51 = blend_k*cs50
               cs52 = cs51*cs6
               cs53 = cs52*d(1, ia)
               cs54 = -1.0_wp/3.0_wp*blend_k*cs20
               cs55 = cs52*(cs17*(1.0_wp - cs47) - cs49 - cs54)
               cs56 = cs27*cs45
               cs57 = (1.0_wp/9.0_wp)*cs56
               cs58 = 3.0_wp*cs27
               cs59 = cs39 + cs58
               cs60 = cs17*(1.0_wp - cs57) - cs54 - cs59
               cs61 = cs17*cs45
               cs62 = cs52*d(3, ia)
               cs63 = cs29*cs45
               cs64 = (1.0_wp/9.0_wp)*cs63
               cs65 = 3.0_wp*cs29
               cs66 = cs40 + cs65
               cs67 = cs17*(1.0_wp - cs64) - cs54 - cs66
               cs68 = cs52*d(2, ia)
               cs69 = (4.0_wp/9.0_wp)*cs46
               cs70 = -2.0_wp*blend_k*cs20
               cs71 = 2.0_wp*cs35 + cs48
               cs72 = cs51*cs8
               cs73 = cs72*d(1, ia)
               cs74 = -2.0_wp/3.0_wp*blend_k*cs20
               cs75 = cs72*(cs17*(1.0_wp - cs69) - cs71 - cs74)
               cs76 = (4.0_wp/9.0_wp)*cs56
               cs77 = 2.0_wp*cs39 + cs58
               cs78 = cs17*(1.0_wp - cs76) - cs74 - cs77
               cs79 = cs72*d(3, ia)
               cs80 = (4.0_wp/9.0_wp)*cs63
               cs81 = 2.0_wp*cs40 + cs65
               cs82 = cs17*(1.0_wp - cs80) - cs74 - cs81
               cs83 = cs72*d(2, ia)
               cs84 = -3.0_wp*blend_k*cs20
               cs85 = cs15*cs48 + cs48
               cs86 = cs10*cs50
               cs87 = cs86*d(1, ia)
               cs88 = cs86*(cs17*(1.0_wp - cs46) - cs44 - cs85)
               cs89 = cs15*cs58 + cs58
               cs90 = cs17*(1.0_wp - cs56) - cs44 - cs89
               cs91 = cs15*cs65 + cs65
               cs92 = cs17*(1.0_wp - cs63) - cs44 - cs91
               cs93 = cs86*d(2, ia)
               cs94 = cs86*d(3, ia)
               acc_ps0_p1 = acc_ps0_p1 + (u)
               acc_ps0_p2 = acc_ps0_p2 + (cs0)
               acc_ps0_p3 = acc_ps0_p3 + (cs1)
               acc_ps1_p1_0 = acc_ps1_p1_0 + (-cs5*cs6)
               acc_ps1_p1_1 = acc_ps1_p1_1 + (-cs7*d(2, ia))
               acc_ps1_p1_2 = acc_ps1_p1_2 + (-cs7*d(3, ia))
               acc_ps1_p2_0 = acc_ps1_p2_0 + (-cs5*cs8)
               acc_ps1_p2_1 = acc_ps1_p2_1 + (-cs9*d(2, ia))
               acc_ps1_p2_2 = acc_ps1_p2_2 + (-cs9*d(3, ia))
               acc_ps1_p3_0 = acc_ps1_p3_0 + (-cs11*d(1, ia))
               acc_ps1_p3_1 = acc_ps1_p3_1 + (-cs11*d(2, ia))
               acc_ps1_p3_2 = acc_ps1_p3_2 + (-cs11*d(3, ia))
               acc_ps2_p1_00 = acc_ps2_p1_00 + (cs23*(cs14*cs16 + cs19))
               acc_ps2_p1_01 = acc_ps2_p1_01 + (cs24*cs25)
               acc_ps2_p1_02 = acc_ps2_p1_02 + (cs26*d(1, ia))
               acc_ps2_p1_11 = acc_ps2_p1_11 + (cs23*(cs16*cs27 + cs28))
               acc_ps2_p1_12 = acc_ps2_p1_12 + (cs26*d(2, ia))
               acc_ps2_p1_22 = acc_ps2_p1_22 + (cs23*(cs16*cs29 + cs30))
               acc_ps2_p2_00 = acc_ps2_p2_00 + (cs32*(cs14*cs31 + cs19))
               acc_ps2_p2_01 = acc_ps2_p2_01 + (cs24*cs33)
               acc_ps2_p2_02 = acc_ps2_p2_02 + (cs34*d(1, ia))
               acc_ps2_p2_11 = acc_ps2_p2_11 + (cs32*(cs27*cs31 + cs28))
               acc_ps2_p2_12 = acc_ps2_p2_12 + (cs34*d(2, ia))
               acc_ps2_p2_22 = acc_ps2_p2_22 + (cs32*(cs29*cs31 + cs30))
               acc_ps2_p3_00 = acc_ps2_p3_00 + (cs36*(cs19 + cs35))
               acc_ps2_p3_01 = acc_ps2_p3_01 + (cs24*cs37)
               acc_ps2_p3_02 = acc_ps2_p3_02 + (cs38*d(1, ia))
               acc_ps2_p3_11 = acc_ps2_p3_11 + (cs36*(cs28 + cs39))
               acc_ps2_p3_12 = acc_ps2_p3_12 + (cs38*d(2, ia))
               acc_ps2_p3_22 = acc_ps2_p3_22 + (cs36*(cs30 + cs40))
               acc_ps3_p1_000 = acc_ps3_p1_000 + (cs53*(cs17*(3.0_wp - cs47) - cs44 - cs49))
               acc_ps3_p1_001 = acc_ps3_p1_001 + (cs55*d(2, ia))
               acc_ps3_p1_002 = acc_ps3_p1_002 + (cs55*d(3, ia))
               acc_ps3_p1_011 = acc_ps3_p1_011 + (cs53*cs60)
               acc_ps3_p1_012 = acc_ps3_p1_012 + (cs24*cs62*(-cs15 - 1.0_wp/9.0_wp*cs61 - 3.0_wp))
               acc_ps3_p1_022 = acc_ps3_p1_022 + (cs53*cs67)
               acc_ps3_p1_111 = acc_ps3_p1_111 + (cs68*(cs17*(3.0_wp - cs57) - cs44 - cs59))
               acc_ps3_p1_112 = acc_ps3_p1_112 + (cs60*cs62)
               acc_ps3_p1_122 = acc_ps3_p1_122 + (cs67*cs68)
               acc_ps3_p1_222 = acc_ps3_p1_222 + (cs62*(cs17*(3.0_wp - cs64) - cs44 - cs66))
               acc_ps3_p2_000 = acc_ps3_p2_000 + (cs73*(cs17*(3.0_wp - cs69) - cs70 - cs71))
               acc_ps3_p2_001 = acc_ps3_p2_001 + (cs75*d(2, ia))
               acc_ps3_p2_002 = acc_ps3_p2_002 + (cs75*d(3, ia))
               acc_ps3_p2_011 = acc_ps3_p2_011 + (cs73*cs78)
               acc_ps3_p2_012 = &
                  acc_ps3_p2_012 + (cs24*cs79*(-2.0_wp*cs15 - 4.0_wp/9.0_wp*cs61 - 3.0_wp))
               acc_ps3_p2_022 = acc_ps3_p2_022 + (cs73*cs82)
               acc_ps3_p2_111 = acc_ps3_p2_111 + (cs83*(cs17*(3.0_wp - cs76) - cs70 - cs77))
               acc_ps3_p2_112 = acc_ps3_p2_112 + (cs78*cs79)
               acc_ps3_p2_122 = acc_ps3_p2_122 + (cs82*cs83)
               acc_ps3_p2_222 = acc_ps3_p2_222 + (cs79*(cs17*(3.0_wp - cs80) - cs70 - cs81))
               acc_ps3_p3_000 = acc_ps3_p3_000 + (cs87*(cs17*(3.0_wp - cs46) - cs84 - cs85))
               acc_ps3_p3_001 = acc_ps3_p3_001 + (cs88*d(2, ia))
               acc_ps3_p3_002 = acc_ps3_p3_002 + (cs88*d(3, ia))
               acc_ps3_p3_011 = acc_ps3_p3_011 + (cs87*cs90)
               acc_ps3_p3_012 = &
                  acc_ps3_p3_012 + (cs87*d(2, ia)*d(3, ia)*(-3.0_wp*cs15 - cs61 - 3.0_wp))
               acc_ps3_p3_022 = acc_ps3_p3_022 + (cs87*cs92)
               acc_ps3_p3_111 = acc_ps3_p3_111 + (cs93*(cs17*(3.0_wp - cs56) - cs84 - cs89))
               acc_ps3_p3_112 = acc_ps3_p3_112 + (cs90*cs94)
               acc_ps3_p3_122 = acc_ps3_p3_122 + (cs92*cs93)
               acc_ps3_p3_222 = acc_ps3_p3_222 + (cs94*(cs17*(3.0_wp - cs63) - cs84 - cs91))
               if (include_q) then
                  cs2 = (u*sqrt(u))
                  cs12 = (1.0_wp/2.0_wp)*cs2
                  cs13 = cs12*cs4
                  cs41 = cs12*cs22
                  cs42 = cs41*((1.0_wp/2.0_wp)*cs15 + 1.0_wp)
                  cs43 = cs42*d(3, ia)
                  cs95 = (1.0_wp/4.0_wp)*cs46
                  cs96 = -3.0_wp/2.0_wp*blend_k*cs20
                  cs97 = (3.0_wp/2.0_wp)*cs35 + cs48
                  cs98 = cs12*cs51
                  cs99 = cs98*d(1, ia)
                  cs100 = -1.0_wp/2.0_wp*blend_k*cs20
                  cs101 = cs98*(-cs100 + cs17*(1.0_wp - cs95) - cs97)
                  cs102 = (1.0_wp/4.0_wp)*cs56
                  cs103 = (3.0_wp/2.0_wp)*cs39 + cs58
                  cs104 = -cs100 - cs103 + cs17*(1.0_wp - cs102)
                  cs105 = cs98*d(3, ia)
                  cs106 = (1.0_wp/4.0_wp)*cs63
                  cs107 = (3.0_wp/2.0_wp)*cs40 + cs65
                  cs108 = -cs100 - cs107 + cs17*(1.0_wp - cs106)
                  cs109 = cs98*d(2, ia)
                  acc_ps0_q = acc_ps0_q + (cs2)
                  acc_ps1_q_0 = acc_ps1_q_0 + (-cs12*cs5)
                  acc_ps1_q_1 = acc_ps1_q_1 + (-cs13*d(2, ia))
                  acc_ps1_q_2 = acc_ps1_q_2 + (-cs13*d(3, ia))
                  acc_ps2_q_00 = acc_ps2_q_00 + (cs41*(cs19 + (1.0_wp/2.0_wp)*cs35))
                  acc_ps2_q_01 = acc_ps2_q_01 + (cs24*cs42)
                  acc_ps2_q_02 = acc_ps2_q_02 + (cs43*d(1, ia))
                  acc_ps2_q_11 = acc_ps2_q_11 + (cs41*(cs28 + (1.0_wp/2.0_wp)*cs39))
                  acc_ps2_q_12 = acc_ps2_q_12 + (cs43*d(2, ia))
                  acc_ps2_q_22 = acc_ps2_q_22 + (cs41*(cs30 + (1.0_wp/2.0_wp)*cs40))
                  acc_ps3_q_000 = acc_ps3_q_000 + (cs99*(cs17*(3.0_wp - cs95) - cs96 - cs97))
                  acc_ps3_q_001 = acc_ps3_q_001 + (cs101*d(2, ia))
                  acc_ps3_q_002 = acc_ps3_q_002 + (cs101*d(3, ia))
                  acc_ps3_q_011 = acc_ps3_q_011 + (cs104*cs99)
                  acc_ps3_q_012 = &
                     acc_ps3_q_012 + (cs105*cs24*(-3.0_wp/2.0_wp*cs15 - 1.0_wp/4.0_wp*cs61 - &
                     3.0_wp))
                  acc_ps3_q_022 = acc_ps3_q_022 + (cs108*cs99)
                  acc_ps3_q_111 = acc_ps3_q_111 + (cs109*(-cs103 + cs17*(3.0_wp - cs102) - cs96))
                  acc_ps3_q_112 = acc_ps3_q_112 + (cs104*cs105)
                  acc_ps3_q_122 = acc_ps3_q_122 + (cs108*cs109)
                  acc_ps3_q_222 = acc_ps3_q_222 + (cs105*(-cs107 + cs17*(3.0_wp - cs106) - cs96))
               end if
            end do

            !> Broadcast the symmetric orbits into the caller's dense tensors
            ps0(1) = acc_ps0_p1
            ps0(2) = acc_ps0_p2
            ps0(3) = acc_ps0_p3
            ps0(4) = acc_ps0_q
            ps1(1, 1) = acc_ps1_p1_0
            ps1(2, 1) = acc_ps1_p1_1
            ps1(3, 1) = acc_ps1_p1_2
            ps1(1, 2) = acc_ps1_p2_0
            ps1(2, 2) = acc_ps1_p2_1
            ps1(3, 2) = acc_ps1_p2_2
            ps1(1, 3) = acc_ps1_p3_0
            ps1(2, 3) = acc_ps1_p3_1
            ps1(3, 3) = acc_ps1_p3_2
            ps1(1, 4) = acc_ps1_q_0
            ps1(2, 4) = acc_ps1_q_1
            ps1(3, 4) = acc_ps1_q_2
            ps2(1, 1, 1) = acc_ps2_p1_00
            ps2(1, 2, 1) = acc_ps2_p1_01
            ps2(2, 1, 1) = acc_ps2_p1_01
            ps2(1, 3, 1) = acc_ps2_p1_02
            ps2(3, 1, 1) = acc_ps2_p1_02
            ps2(2, 2, 1) = acc_ps2_p1_11
            ps2(2, 3, 1) = acc_ps2_p1_12
            ps2(3, 2, 1) = acc_ps2_p1_12
            ps2(3, 3, 1) = acc_ps2_p1_22
            ps2(1, 1, 2) = acc_ps2_p2_00
            ps2(1, 2, 2) = acc_ps2_p2_01
            ps2(2, 1, 2) = acc_ps2_p2_01
            ps2(1, 3, 2) = acc_ps2_p2_02
            ps2(3, 1, 2) = acc_ps2_p2_02
            ps2(2, 2, 2) = acc_ps2_p2_11
            ps2(2, 3, 2) = acc_ps2_p2_12
            ps2(3, 2, 2) = acc_ps2_p2_12
            ps2(3, 3, 2) = acc_ps2_p2_22
            ps2(1, 1, 3) = acc_ps2_p3_00
            ps2(1, 2, 3) = acc_ps2_p3_01
            ps2(2, 1, 3) = acc_ps2_p3_01
            ps2(1, 3, 3) = acc_ps2_p3_02
            ps2(3, 1, 3) = acc_ps2_p3_02
            ps2(2, 2, 3) = acc_ps2_p3_11
            ps2(2, 3, 3) = acc_ps2_p3_12
            ps2(3, 2, 3) = acc_ps2_p3_12
            ps2(3, 3, 3) = acc_ps2_p3_22
            ps2(1, 1, 4) = acc_ps2_q_00
            ps2(1, 2, 4) = acc_ps2_q_01
            ps2(2, 1, 4) = acc_ps2_q_01
            ps2(1, 3, 4) = acc_ps2_q_02
            ps2(3, 1, 4) = acc_ps2_q_02
            ps2(2, 2, 4) = acc_ps2_q_11
            ps2(2, 3, 4) = acc_ps2_q_12
            ps2(3, 2, 4) = acc_ps2_q_12
            ps2(3, 3, 4) = acc_ps2_q_22
            ps3(1, 1, 1, 1) = acc_ps3_p1_000
            ps3(1, 1, 2, 1) = acc_ps3_p1_001
            ps3(1, 2, 1, 1) = acc_ps3_p1_001
            ps3(2, 1, 1, 1) = acc_ps3_p1_001
            ps3(1, 1, 3, 1) = acc_ps3_p1_002
            ps3(1, 3, 1, 1) = acc_ps3_p1_002
            ps3(3, 1, 1, 1) = acc_ps3_p1_002
            ps3(1, 2, 2, 1) = acc_ps3_p1_011
            ps3(2, 1, 2, 1) = acc_ps3_p1_011
            ps3(2, 2, 1, 1) = acc_ps3_p1_011
            ps3(1, 2, 3, 1) = acc_ps3_p1_012
            ps3(1, 3, 2, 1) = acc_ps3_p1_012
            ps3(2, 1, 3, 1) = acc_ps3_p1_012
            ps3(2, 3, 1, 1) = acc_ps3_p1_012
            ps3(3, 1, 2, 1) = acc_ps3_p1_012
            ps3(3, 2, 1, 1) = acc_ps3_p1_012
