   end subroutine svdw_atom_eval

   pure module subroutine svdw_atom_rad_eval(d_a, R_a, blend_k, max_deriv, atd0, atd1, atd2, atd3, x_a, &
                                      inv_x_a, u_a, fade_start, fade_width)
      !> Displacement r - R_A of the active atom
      real(wp), intent(in) :: d_a(3)
      !> Radius of the active atom
      real(wp), intent(in) :: R_a
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> Highest spatial-derivative order to set (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> Order-0 radius kind tensor of this atom
      real(wp), intent(out) :: atd0(nkind)
      !> Order-1 radius kind tensor of this atom
      real(wp), intent(out) :: atd1(3, nkind)
      !> Order-2 radius kind tensor of this atom
      real(wp), intent(out) :: atd2(3, 3, nkind)
      !> Order-3 radius kind tensor of this atom
      real(wp), intent(out) :: atd3(3, 3, 3, nkind)
      !> Distance ||d_a|| of this atom, stage-1 `cache_x` of this point and atom
      real(wp), intent(in) :: x_a
      !> Reciprocal distance 1/x_a, stage-1 `cache_inv_x`; read by the faded branch at orders >= 1
      !> only (Inf on a nucleus)
      real(wp), intent(in) :: inv_x_a
      !> Screening factor exp(-(blend_k/3)(x_a - R_a)) before the fade, gate-masked: stage-1
      !> `cache_u` (inline exp), 0 where the strip's hard screening dropped the atom
      real(wp), intent(in) :: u_a
      !> Fade onset X_on in d_A, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width Delta in d_A, as passed to the strip kernel; > 0
      real(wp), intent(in) :: fade_width

      !> Fade of this atom: band end, reciprocal width, raw and clamped s, t, ds/dd
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k and s**k sqrt(s) of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5, fsp6, fsp7, fsp8, fsp9, fsp10, fsp11, fsp12, fsp13
      real(wp) :: fsp14, fsp15, fsq, fsh3, fsh4, fsh5, fsh6, fsh7

      if (x_a - R_a > fade_start) then
         ! In or beyond the band: faded atom function, the strip kernel's fade
         if (.not. fade_width > 0.0_wp) error stop &
            "svdw_atom_rad_eval: fade_width must be positive"
         band_end = fade_start + fade_width
         inv_delta = 1.0_wp/fade_width
         sr = (band_end - (x_a - R_a))*inv_delta
         fs = min(max(sr, 0.0_wp), 1.0_wp)
         ft = min(max((x_a - R_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
         dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
         fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
         fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
         fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
         fp3 = -1680.0_wp*ft - 210.0_wp
         fp4 = 1680.0_wp
         fsp1 = fs
         fsp2 = fsp1*fs
         fsp3 = fsp2*fs
         fsp4 = fsp3*fs
         fsp5 = fsp4*fs
         fsp6 = fsp5*fs
         fsp7 = fsp6*fs
         fsp8 = fsp7*fs
         fsp9 = fsp8*fs
         fsp10 = fsp9*fs
         fsp11 = fsp10*fs
         fsp12 = fsp11*fs
         fsp13 = fsp12*fs
         fsp14 = fsp13*fs
         fsp15 = fsp14*fs
         fsq = sqrt(fs)
         fsh3 = fsp3*fsq
         fsh4 = fsp4*fsq
         fsh5 = fsp5*fsq
         fsh6 = fsp6*fsq
         fsh7 = fsp7*fsq
         select case (max_deriv)
         case (0)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: cs0, cs1, cs2

               cs0 = (fp0*fp0)
               cs1 = (fp0*fp0*fp0)
               cs2 = (fp0*sqrt(fp0))
               atd0(1) = -u_a*(-1.0_wp/3.0_wp*blend_k*fp0*fsp5 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5))
               atd0(2) = &
                  -(u_a*u_a)*(-2.0_wp/3.0_wp*blend_k*cs0*fsp10 + dsdd*(10.0_wp*cs0*fsp9 + &
                  2.0_wp*fp0*fp1*fsp10))
               atd0(3) = &
                  -(u_a*u_a*u_a)*(-blend_k*cs1*fsp15 + dsdd*(3.0_wp*cs0*fp1*fsp15 + &
                  15.0_wp*cs1*fsp14))
               atd0(4) = &
                  -(u_a*sqrt(u_a))*(-1.0_wp/2.0_wp*blend_k*cs2*fsh7 + &
                  dsdd*((15.0_wp/2.0_wp)*cs2*fsh6 + (3.0_wp/2.0_wp)*sqrt(fp0)*fp1*fsh7))
            end block
         case (1)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
               real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25
               real(wp) :: cs26, cs27, cs28, cs29, cs30, cs31

               cs0 = fp0*fsp5
               cs1 = 5.0_wp*fp0*fsp4 + fp1*fsp5
               cs2 = (u_a*u_a)
               cs3 = (2.0_wp/3.0_wp)*blend_k
               cs4 = (fp0*fp0)
               cs5 = cs4*fsp10
               cs6 = 10.0_wp*cs4*fsp9 + 2.0_wp*fp0*fp1*fsp10
               cs7 = (u_a*u_a*u_a)
               cs8 = (fp0*fp0*fp0)
               cs9 = cs8*fsp15
               cs10 = 3.0_wp*cs4*fp1*fsp15 + 15.0_wp*cs8*fsp14
               cs11 = (u_a*sqrt(u_a))
               cs12 = (fp0*sqrt(fp0))
               cs13 = cs12*fsh7
               cs14 = sqrt(fp0)
               cs15 = (15.0_wp/2.0_wp)*cs12*fsh6 + (3.0_wp/2.0_wp)*cs14*fp1*fsh7
               cs16 = d_a(1)*inv_x_a
               cs17 = (blend_k*blend_k)
               cs18 = (dsdd*dsdd)
               cs19 = 20.0_wp*fp0
               cs20 = fp1*fs
               cs21 = &
                  u_a*((1.0_wp/9.0_wp)*cs0*cs17 - cs1*cs3*dsdd + cs18*fsp3*(cs19 + 10.0_wp*cs20 + &
                  fp2*fsp2))
               cs22 = cs21*inv_x_a
