            atd3(1, 2, 2, 1) = t_atd3_p1_011
            atd3(2, 1, 2, 1) = t_atd3_p1_011
            atd3(2, 2, 1, 1) = t_atd3_p1_011
            t_atd3_p1_012 = cs25*cs62*(-cs16 - 1.0_wp/9.0_wp*cs61 - 3.0_wp)
            atd3(1, 2, 3, 1) = t_atd3_p1_012
            atd3(1, 3, 2, 1) = t_atd3_p1_012
            atd3(2, 1, 3, 1) = t_atd3_p1_012
            atd3(2, 3, 1, 1) = t_atd3_p1_012
            atd3(3, 1, 2, 1) = t_atd3_p1_012
            atd3(3, 2, 1, 1) = t_atd3_p1_012
            t_atd3_p1_022 = cs53*cs67
            atd3(1, 3, 3, 1) = t_atd3_p1_022
            atd3(3, 1, 3, 1) = t_atd3_p1_022
            atd3(3, 3, 1, 1) = t_atd3_p1_022
            atd3(2, 2, 2, 1) = cs68*(cs18*(3.0_wp - cs57) - cs45 - cs59)
            t_atd3_p1_112 = cs60*cs62
            atd3(2, 2, 3, 1) = t_atd3_p1_112
            atd3(2, 3, 2, 1) = t_atd3_p1_112
            atd3(3, 2, 2, 1) = t_atd3_p1_112
            t_atd3_p1_122 = cs67*cs68
            atd3(2, 3, 3, 1) = t_atd3_p1_122
            atd3(3, 2, 3, 1) = t_atd3_p1_122
            atd3(3, 3, 2, 1) = t_atd3_p1_122
            atd3(3, 3, 3, 1) = cs62*(cs18*(3.0_wp - cs64) - cs45 - cs66)
            atd3(1, 1, 1, 2) = cs73*(cs18*(3.0_wp - cs69) - cs70 - cs71)
            t_atd3_p2_001 = cs75*d_a(2)
            atd3(1, 1, 2, 2) = t_atd3_p2_001
            atd3(1, 2, 1, 2) = t_atd3_p2_001
            atd3(2, 1, 1, 2) = t_atd3_p2_001
            t_atd3_p2_002 = cs75*d_a(3)
            atd3(1, 1, 3, 2) = t_atd3_p2_002
            atd3(1, 3, 1, 2) = t_atd3_p2_002
            atd3(3, 1, 1, 2) = t_atd3_p2_002
            t_atd3_p2_011 = cs73*cs78
            atd3(1, 2, 2, 2) = t_atd3_p2_011
            atd3(2, 1, 2, 2) = t_atd3_p2_011
            atd3(2, 2, 1, 2) = t_atd3_p2_011
            t_atd3_p2_012 = cs25*cs79*(-2.0_wp*cs16 - 4.0_wp/9.0_wp*cs61 - 3.0_wp)
            atd3(1, 2, 3, 2) = t_atd3_p2_012
            atd3(1, 3, 2, 2) = t_atd3_p2_012
            atd3(2, 1, 3, 2) = t_atd3_p2_012
            atd3(2, 3, 1, 2) = t_atd3_p2_012
            atd3(3, 1, 2, 2) = t_atd3_p2_012
            atd3(3, 2, 1, 2) = t_atd3_p2_012
            t_atd3_p2_022 = cs73*cs82
            atd3(1, 3, 3, 2) = t_atd3_p2_022
            atd3(3, 1, 3, 2) = t_atd3_p2_022
            atd3(3, 3, 1, 2) = t_atd3_p2_022
            atd3(2, 2, 2, 2) = cs83*(cs18*(3.0_wp - cs76) - cs70 - cs77)
            t_atd3_p2_112 = cs78*cs79
            atd3(2, 2, 3, 2) = t_atd3_p2_112
            atd3(2, 3, 2, 2) = t_atd3_p2_112
            atd3(3, 2, 2, 2) = t_atd3_p2_112
            t_atd3_p2_122 = cs82*cs83
            atd3(2, 3, 3, 2) = t_atd3_p2_122
            atd3(3, 2, 3, 2) = t_atd3_p2_122
            atd3(3, 3, 2, 2) = t_atd3_p2_122
            atd3(3, 3, 3, 2) = cs79*(cs18*(3.0_wp - cs80) - cs70 - cs81)
            atd3(1, 1, 1, 3) = cs87*(cs18*(3.0_wp - cs46) - cs84 - cs85)
            t_atd3_p3_001 = cs88*d_a(2)
            atd3(1, 1, 2, 3) = t_atd3_p3_001
            atd3(1, 2, 1, 3) = t_atd3_p3_001
            atd3(2, 1, 1, 3) = t_atd3_p3_001
            t_atd3_p3_002 = cs88*d_a(3)
            atd3(1, 1, 3, 3) = t_atd3_p3_002
            atd3(1, 3, 1, 3) = t_atd3_p3_002
            atd3(3, 1, 1, 3) = t_atd3_p3_002
            t_atd3_p3_011 = cs87*cs90
            atd3(1, 2, 2, 3) = t_atd3_p3_011
            atd3(2, 1, 2, 3) = t_atd3_p3_011
            atd3(2, 2, 1, 3) = t_atd3_p3_011
            t_atd3_p3_012 = cs87*d_a(2)*d_a(3)*(-3.0_wp*cs16 - cs61 - 3.0_wp)
            atd3(1, 2, 3, 3) = t_atd3_p3_012
            atd3(1, 3, 2, 3) = t_atd3_p3_012
            atd3(2, 1, 3, 3) = t_atd3_p3_012
            atd3(2, 3, 1, 3) = t_atd3_p3_012
            atd3(3, 1, 2, 3) = t_atd3_p3_012
            atd3(3, 2, 1, 3) = t_atd3_p3_012
            t_atd3_p3_022 = cs87*cs92
            atd3(1, 3, 3, 3) = t_atd3_p3_022
            atd3(3, 1, 3, 3) = t_atd3_p3_022
            atd3(3, 3, 1, 3) = t_atd3_p3_022
            atd3(2, 2, 2, 3) = cs93*(cs18*(3.0_wp - cs56) - cs84 - cs89)
            t_atd3_p3_112 = cs90*cs94
            atd3(2, 2, 3, 3) = t_atd3_p3_112
            atd3(2, 3, 2, 3) = t_atd3_p3_112
            atd3(3, 2, 2, 3) = t_atd3_p3_112
            t_atd3_p3_122 = cs92*cs93
            atd3(2, 3, 3, 3) = t_atd3_p3_122
            atd3(3, 2, 3, 3) = t_atd3_p3_122
            atd3(3, 3, 2, 3) = t_atd3_p3_122
            atd3(3, 3, 3, 3) = cs94*(cs18*(3.0_wp - cs63) - cs84 - cs91)
            atd3(1, 1, 1, 4) = cs99*(cs18*(3.0_wp - cs95) - cs96 - cs97)
            t_atd3_q_001 = cs101*d_a(2)
            atd3(1, 1, 2, 4) = t_atd3_q_001
            atd3(1, 2, 1, 4) = t_atd3_q_001
            atd3(2, 1, 1, 4) = t_atd3_q_001
            t_atd3_q_002 = cs101*d_a(3)
            atd3(1, 1, 3, 4) = t_atd3_q_002
            atd3(1, 3, 1, 4) = t_atd3_q_002
            atd3(3, 1, 1, 4) = t_atd3_q_002
            t_atd3_q_011 = cs104*cs99
            atd3(1, 2, 2, 4) = t_atd3_q_011
            atd3(2, 1, 2, 4) = t_atd3_q_011
            atd3(2, 2, 1, 4) = t_atd3_q_011
            t_atd3_q_012 = cs105*cs25*(-3.0_wp/2.0_wp*cs16 - 1.0_wp/4.0_wp*cs61 - 3.0_wp)
            atd3(1, 2, 3, 4) = t_atd3_q_012
            atd3(1, 3, 2, 4) = t_atd3_q_012
            atd3(2, 1, 3, 4) = t_atd3_q_012
            atd3(2, 3, 1, 4) = t_atd3_q_012
            atd3(3, 1, 2, 4) = t_atd3_q_012
            atd3(3, 2, 1, 4) = t_atd3_q_012
            t_atd3_q_022 = cs108*cs99
            atd3(1, 3, 3, 4) = t_atd3_q_022
            atd3(3, 1, 3, 4) = t_atd3_q_022
            atd3(3, 3, 1, 4) = t_atd3_q_022
            atd3(2, 2, 2, 4) = cs109*(-cs103 + cs18*(3.0_wp - cs102) - cs96)
            t_atd3_q_112 = cs104*cs105
            atd3(2, 2, 3, 4) = t_atd3_q_112
            atd3(2, 3, 2, 4) = t_atd3_q_112
            atd3(3, 2, 2, 4) = t_atd3_q_112
            t_atd3_q_122 = cs108*cs109
            atd3(2, 3, 3, 4) = t_atd3_q_122
            atd3(3, 2, 3, 4) = t_atd3_q_122
            atd3(3, 3, 2, 4) = t_atd3_q_122
            atd3(3, 3, 3, 4) = cs105*(-cs107 + cs18*(3.0_wp - cs106) - cs96)
         end block
      end select

   end subroutine svdw_atom_rad_eval

   pure module subroutine svdw_atom_radrad_eval(d_a, R_a, blend_k, max_deriv, atdd0, atdd1, atdd2, x_a, &
                                         inv_x_a, u_a, fade_start, fade_width)
      !> Displacement r - R_A of the active atom
      real(wp), intent(in) :: d_a(3)
      !> Radius of the active atom
      real(wp), intent(in) :: R_a
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> Highest spatial-derivative order to set (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> Order-0 second radius kind tensor of this atom
      real(wp), intent(out) :: atdd0(nkind)
      !> Order-1 second radius kind tensor of this atom
      real(wp), intent(out) :: atdd1(3, nkind)
      !> Order-2 second radius kind tensor of this atom
      real(wp), intent(out) :: atdd2(3, 3, nkind)
      !> Distance ||d_a|| of this atom, stage-1 `cache_x` of this point and atom
      real(wp), intent(in) :: x_a
      !> Reciprocal distance 1/x_a, stage-1 `cache_inv_x`; read by the faded branch at orders >= 1
      !> only (Inf on a nucleus)
      real(wp), intent(in) :: inv_x_a
      !> Screening factor exp(-(blend_k/3)(x_a - R_a)) before the fade, gate-masked: stage-1
      !> `cache_u` (inline exp), 0 where the strip's hard screening dropped the atom
      real(wp), intent(in) :: u_a
      !> Fade onset X_on in d_A, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width Delta in d_A, as passed to the strip kernel; > 0
      real(wp), intent(in) :: fade_width

      !> Fade of this atom: band end, reciprocal width, raw and clamped s, t, ds/dd
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k and s**k sqrt(s) of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5, fsp6, fsp7, fsp8, fsp9, fsp10, fsp11, fsp12, fsp13
      real(wp) :: fsp14, fsp15, fsq, fsh3, fsh4, fsh5, fsh6, fsh7

      if (x_a - R_a > fade_start) then
         ! In or beyond the band: faded atom function, the strip kernel's fade
         if (.not. fade_width > 0.0_wp) error stop &
            "svdw_atom_radrad_eval: fade_width must be positive"
         band_end = fade_start + fade_width
         inv_delta = 1.0_wp/fade_width
         sr = (band_end - (x_a - R_a))*inv_delta
         fs = min(max(sr, 0.0_wp), 1.0_wp)
         ft = min(max((x_a - R_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
         dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
         fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
         fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
         fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
         fp3 = -1680.0_wp*ft - 210.0_wp
         fp4 = 1680.0_wp
         fsp1 = fs
         fsp2 = fsp1*fs
         fsp3 = fsp2*fs
         fsp4 = fsp3*fs
         fsp5 = fsp4*fs
         fsp6 = fsp5*fs
         fsp7 = fsp6*fs
         fsp8 = fsp7*fs
         fsp9 = fsp8*fs
         fsp10 = fsp9*fs
         fsp11 = fsp10*fs
         fsp12 = fsp11*fs
         fsp13 = fsp12*fs
         fsp14 = fsp13*fs
         fsp15 = fsp14*fs
         fsq = sqrt(fs)
         fsh3 = fsp3*fsq
         fsh4 = fsp4*fsq
         fsh5 = fsp5*fsq
         fsh6 = fsp6*fsq
         fsh7 = fsp7*fsq
         select case (max_deriv)
         case (0)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11

               cs0 = (blend_k*blend_k)
               cs1 = blend_k*dsdd
               cs2 = (dsdd*dsdd)
               cs3 = 20.0_wp*fp0
               cs4 = fp1*fs
               cs5 = (fp0*fp0)
               cs6 = (fp1*fp1)
               cs7 = fp0*fp2
               cs8 = (fp0*fp0*fp0)
               cs9 = 30.0_wp*cs4
               cs10 = (fp0*sqrt(fp0))
               cs11 = sqrt(fp0)
               atdd0(1) = &
                  u_a*((1.0_wp/9.0_wp)*cs0*fp0*fsp5 - 2.0_wp/3.0_wp*cs1*(5.0_wp*fp0*fsp4 + &
                  fp1*fsp5) + cs2*fsp3*(cs3 + 10.0_wp*cs4 + fp2*fsp2))
               atdd0(2) = &
                  (u_a*u_a)*((4.0_wp/9.0_wp)*cs0*cs5*fsp10 - 4.0_wp/3.0_wp*cs1*(10.0_wp*cs5*fsp9 + &
                  2.0_wp*fp0*fp1*fsp10) + 2.0_wp*cs2*fsp8*(cs3*cs4 + 45.0_wp*cs5 + fsp2*(cs6 + &
                  cs7)))
               atdd0(3) = &
                  (u_a*u_a*u_a)*(cs0*cs8*fsp15 - 2.0_wp*cs1*(3.0_wp*cs5*fp1*fsp15 + &
                  15.0_wp*cs8*fsp14) + 3.0_wp*cs2*fp0*fsp13*(70.0_wp*cs5 + cs9*fp0 + &
                  fsp2*(2.0_wp*cs6 + cs7)))
               atdd0(4) = &
                  (u_a*sqrt(u_a))*((1.0_wp/4.0_wp)*cs0*cs10*fsh7 - cs1*((15.0_wp/2.0_wp)*cs10*fsh6 &
                  + (3.0_wp/2.0_wp)*cs11*fp1*fsh7) + (3.0_wp/4.0_wp)*cs2*fsh5*(65.0_wp*cs10 + &
                  cs11*cs9 + fsp2*(2.0_wp*cs11*fp2 + cs6/cs11)))
            end block
         case (1)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
               real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25
               real(wp) :: cs26, cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37
               real(wp) :: cs38, cs39, cs40, cs41, cs42, cs43, cs44, cs45

               cs0 = (blend_k*blend_k)
               cs1 = fp0*fsp5
               cs2 = 5.0_wp*fp0*fsp4 + fp1*fsp5
               cs3 = blend_k*dsdd
               cs4 = (dsdd*dsdd)
               cs5 = 20.0_wp*fp0
               cs6 = fp2*fsp2
               cs7 = fp1*fs
               cs8 = cs4*fsp3*(cs5 + cs6 + 10.0_wp*cs7)
               cs9 = (u_a*u_a)
               cs10 = (fp0*fp0)
               cs11 = cs10*fsp10
               cs12 = 10.0_wp*cs10*fsp9 + 2.0_wp*fp0*fp1*fsp10
               cs13 = (fp1*fp1)
               cs14 = fp0*fp2
               cs15 = fsp2*(cs13 + cs14)
               cs16 = cs4*fsp8*(45.0_wp*cs10 + cs15 + cs5*cs7)
               cs17 = (u_a*u_a*u_a)
               cs18 = (fp0*fp0*fp0)
               cs19 = cs18*fsp15
               cs20 = 3.0_wp*fp1
               cs21 = cs10*cs20*fsp15 + 15.0_wp*cs18*fsp14
               cs22 = 30.0_wp*cs7
               cs23 = fsp2*(2.0_wp*cs13 + cs14)
               cs24 = cs4*fp0*fsp13*(70.0_wp*cs10 + cs22*fp0 + cs23)
               cs25 = (u_a*sqrt(u_a))
               cs26 = (fp0*sqrt(fp0))
               cs27 = cs26*fsh7
               cs28 = sqrt(fp0)
               cs29 = (15.0_wp/2.0_wp)*cs26*fsh6 + (3.0_wp/2.0_wp)*cs28*fp1*fsh7
               cs30 = 1.0_wp/cs28
               cs31 = fsp2*(cs13*cs30 + 2.0_wp*cs28*fp2)
               cs32 = cs4*fsh5*(cs22*cs28 + 65.0_wp*cs26 + cs31)
               cs33 = d_a(1)*inv_x_a
               cs34 = (blend_k*blend_k*blend_k)
               cs35 = (dsdd*dsdd*dsdd)
               cs36 = &
                  u_a*(-blend_k*cs8 + (1.0_wp/3.0_wp)*cs0*cs2*dsdd - 1.0_wp/27.0_wp*cs1*cs34 + &
                  cs35*fsp2*(15.0_wp*cs6 + 60.0_wp*cs7 + 60.0_wp*fp0 + fp3*fsp3))
               cs37 = cs36*inv_x_a
               cs38 = &
                  cs9*(-4.0_wp*blend_k*cs16 + (4.0_wp/3.0_wp)*cs0*cs12*dsdd - &
                  8.0_wp/27.0_wp*cs11*cs34 + 2.0_wp*cs35*fsp7*(360.0_wp*cs10 + 30.0_wp*cs15 + &
                  270.0_wp*cs7*fp0 + fsp3*(cs20*fp2 + fp0*fp3)))
               cs39 = cs38*inv_x_a
               cs40 = (fp1*fp1*fp1)
               cs41 = 6.0_wp*fp1
               cs42 = &
                  cs17*(-9.0_wp*blend_k*cs24 + 3.0_wp*cs0*cs21*dsdd - cs19*cs34 + &
                  3.0_wp*cs35*fsp12*(630.0_wp*cs10*cs7 + 910.0_wp*cs18 + 45.0_wp*cs23*fp0 + &
                  fsp3*(cs10*fp3 + cs14*cs41 + 2.0_wp*cs40)))
               cs43 = cs42*inv_x_a
               cs44 = &
                  cs25*(-9.0_wp/8.0_wp*blend_k*cs32 + (3.0_wp/4.0_wp)*cs0*cs29*dsdd - &
                  1.0_wp/8.0_wp*cs27*cs34 + (3.0_wp/8.0_wp)*cs35*fsh4*(715.0_wp*cs26 + &
                  585.0_wp*cs28*cs7 + 45.0_wp*cs31 + fsp3*(4.0_wp*cs28*fp3 + cs30*cs41*fp2 - &
                  cs40/cs26)))
               cs45 = cs44*inv_x_a
               atdd0(1) = u_a*((1.0_wp/9.0_wp)*cs0*cs1 - 2.0_wp/3.0_wp*cs2*cs3 + cs8)
               atdd0(2) = cs9*((4.0_wp/9.0_wp)*cs0*cs11 - 4.0_wp/3.0_wp*cs12*cs3 + 2.0_wp*cs16)
               atdd0(3) = cs17*(cs0*cs19 - 2.0_wp*cs21*cs3 + 3.0_wp*cs24)
               atdd0(4) = cs25*((1.0_wp/4.0_wp)*cs0*cs27 - cs29*cs3 + (3.0_wp/4.0_wp)*cs32)
               atdd1(1, 1) = cs33*cs36
               atdd1(2, 1) = cs37*d_a(2)
               atdd1(3, 1) = cs37*d_a(3)
               atdd1(1, 2) = cs33*cs38
               atdd1(2, 2) = cs39*d_a(2)
               atdd1(3, 2) = cs39*d_a(3)
               atdd1(1, 3) = cs33*cs42
               atdd1(2, 3) = cs43*d_a(2)
               atdd1(3, 3) = cs43*d_a(3)
               atdd1(1, 4) = cs33*cs44
               atdd1(2, 4) = cs45*d_a(2)
               atdd1(3, 4) = cs45*d_a(3)
            end block
         case default
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
               real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25
               real(wp) :: cs26, cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37
               real(wp) :: cs38, cs39, cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49
               real(wp) :: cs50, cs51, cs52, cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61
               real(wp) :: cs62, cs63, cs64, cs65, cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73
               real(wp) :: cs74, cs75, cs76, cs77, cs78, cs79, cs80, cs81, cs82, cs83, cs84, cs85
               real(wp) :: cs86, cs87, cs88, cs89, cs90, t_atdd2_p1_01, t_atdd2_p1_02, t_atdd2_p1_12
               real(wp) :: t_atdd2_p2_01, t_atdd2_p2_02, t_atdd2_p2_12, t_atdd2_p3_01, t_atdd2_p3_02
               real(wp) :: t_atdd2_p3_12, t_atdd2_q_01, t_atdd2_q_02, t_atdd2_q_12

               cs0 = (blend_k*blend_k)
               cs1 = fp0*fsp5
               cs2 = 5.0_wp*fp0*fsp4 + fp1*fsp5
               cs3 = blend_k*dsdd
               cs4 = (dsdd*dsdd)
               cs5 = 20.0_wp*fp0
               cs6 = fp2*fsp2
               cs7 = fp1*fs
               cs8 = cs4*fsp3*(cs5 + cs6 + 10.0_wp*cs7)
               cs9 = (u_a*u_a)
               cs10 = (fp0*fp0)
               cs11 = cs10*fsp10
