               cs17 = (u_a*u_a*u_a)
               cs18 = (fp0*fp0*fp0)
               cs19 = cs18*fsp15
               cs20 = 3.0_wp*fp1
               cs21 = cs10*cs20*fsp15 + 15.0_wp*cs18*fsp14
               cs22 = 30.0_wp*cs7
               cs23 = fsp2*(2.0_wp*cs13 + cs14)
               cs24 = cs4*fp0*fsp13*(70.0_wp*cs10 + cs22*fp0 + cs23)
               cs25 = (u_a*sqrt(u_a))
               cs26 = (fp0*sqrt(fp0))
               cs27 = cs26*fsh7
               cs28 = sqrt(fp0)
               cs29 = (15.0_wp/2.0_wp)*cs26*fsh6 + (3.0_wp/2.0_wp)*cs28*fp1*fsh7
               cs30 = 1.0_wp/cs28
               cs31 = fsp2*(cs13*cs30 + 2.0_wp*cs28*fp2)
               cs32 = cs4*fsh5*(cs22*cs28 + 65.0_wp*cs26 + cs31)
               cs33 = (blend_k*blend_k*blend_k)
               cs34 = (dsdd*dsdd*dsdd)
               cs35 = fp3*fsp3
               cs36 = cs35 + 15.0_wp*cs6 + 60.0_wp*cs7 + 60.0_wp*fp0
               cs37 = &
                  u_a*(-blend_k*cs8 + (1.0_wp/3.0_wp)*cs0*cs2*dsdd - 1.0_wp/27.0_wp*cs1*cs33 + &
                  cs34*cs36*fsp2)
               cs38 = cs37*inv_x_a
               cs39 = cs7*fp0
               cs40 = fp0*fp3
               cs41 = fsp3*(cs20*fp2 + cs40)
               cs42 = 360.0_wp*cs10 + 30.0_wp*cs15 + 270.0_wp*cs39 + cs41
               cs43 = &
                  cs9*(-4.0_wp*blend_k*cs16 + (4.0_wp/3.0_wp)*cs0*cs12*dsdd - &
                  8.0_wp/27.0_wp*cs11*cs33 + 2.0_wp*cs34*cs42*fsp7)
               cs44 = cs43*inv_x_a
               cs45 = cs10*cs7
               cs46 = cs23*fp0
               cs47 = (fp1*fp1*fp1)
               cs48 = 6.0_wp*fp1
               cs49 = fsp3*(cs10*fp3 + cs14*cs48 + 2.0_wp*cs47)
               cs50 = 910.0_wp*cs18 + 630.0_wp*cs45 + 45.0_wp*cs46 + cs49
               cs51 = &
                  cs17*(-9.0_wp*blend_k*cs24 + 3.0_wp*cs0*cs21*dsdd - cs19*cs33 + &
