               cs86 = cs64*cs85
               cs87 = cs59*cs62
               cs88 = &
                  -3.0_wp/4.0_wp*blend_k*cs34*cs58*fsh4 + cs0*cs53 + (1.0_wp/16.0_wp)*cs27*cs66 - &
                  1.0_wp/2.0_wp*cs29*cs67 + (3.0_wp/16.0_wp)*cs68*fsh3*(6435.0_wp*cs26 + &
                  1170.0_wp*cs31 + 8580.0_wp*cs54 + 60.0_wp*cs57 + fsp4*(8.0_wp*cs28*fp4 + &
                  12.0_wp*cs30*cs78 + 16.0_wp*cs30*fp1*fp3 - cs56*cs83 + &
                  3.0_wp*(fp1*fp1*fp1*fp1)/(fp0*fp0*sqrt(fp0))))
               cs89 = cs25*cs88
               cs90 = cs64*cs89
               atdd0(1) = u_a*((1.0_wp/9.0_wp)*cs0*cs1 - 2.0_wp/3.0_wp*cs2*cs3 + cs8)
               atdd0(2) = cs9*((4.0_wp/9.0_wp)*cs0*cs11 - 4.0_wp/3.0_wp*cs12*cs3 + 2.0_wp*cs16)
               atdd0(3) = cs17*(cs0*cs19 - 2.0_wp*cs21*cs3 + 3.0_wp*cs24)
               atdd0(4) = cs25*((1.0_wp/4.0_wp)*cs0*cs27 - cs29*cs3 + (3.0_wp/4.0_wp)*cs32)
               atdd1(1, 1) = cs38*d_a(1)
               atdd1(2, 1) = cs38*d_a(2)
               atdd1(3, 1) = cs38*d_a(3)
               atdd1(1, 2) = cs44*d_a(1)
