               t_atdd2_p2_01 = cs64*cs79*cs9*d_a(1)*d_a(2) - cs71*cs77
               atdd2(1, 2, 2) = t_atdd2_p2_01
               atdd2(2, 1, 2) = t_atdd2_p2_01
               t_atdd2_p2_02 = cs64*cs79*cs9*d_a(1)*d_a(3) - cs72*cs77
               atdd2(1, 3, 2) = t_atdd2_p2_02
               atdd2(3, 1, 2) = t_atdd2_p2_02
