            cs2 = (u_a*u_a*u_a)
            cs3 = (u_a*sqrt(u_a))
            cs4 = (blend_k*blend_k*blend_k)
            cs5 = 1.0_wp/x_a
            cs6 = cs4*cs5
            cs7 = cs6*d_a(1)
